-- Domain 4 Recap: Operational Procedures
update lessons set content_blocks = jsonb_set(content_blocks, '{3,terms,2,short}', to_jsonb($t$Cross-platform GUI / encrypted command-line interface (CLI) / fleet management.$t$::text))
