-- ---------------- cissp ----------------

-- The CIA Triad
update lessons set content_blocks = jsonb_set(content_blocks, '{4,example}', to_jsonb($t$A distributed denial-of-service (DDoS) attack takes the company website offline for six hours. No data was exposed or changed, but customers couldn't reach it: an availability failure.$t$::text))
  where id = 'c05bc493-3645-4b09-9702-c5e1f12b8a85' and content_blocks #>> '{4,example}' = $t$A DDoS attack takes the company website offline for six hours. No data was exposed or changed, but customers couldn't reach it: an availability failure.$t$;

-- Risk Management Fundamentals
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$In this lesson, you'll learn the core vocabulary of risk management, asset, threat, vulnerability, and risk, along with the four strategies organizations use to treat risk, and how to calculate risk in dollar terms using single loss expectancy (SLE), annualized rate of occurrence (ARO), and annualized loss expectancy (ALE). By the end, you'll be able to classify a risk scenario and choose, or calculate, the right response.$t$::text))
  where id = 'f1cc6e38-a91f-42b6-a7d5-0dfcd44f9548' and content_blocks #>> '{0,overview}' = $t$In this lesson, you'll learn the core vocabulary of risk management, asset, threat, vulnerability, and risk, along with the four strategies organizations use to treat risk, and how to calculate risk in dollar terms using SLE, ARO, and ALE. By the end, you'll be able to classify a risk scenario and choose, or calculate, the right response.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,caption}', to_jsonb($t$Remove any link and the risk disappears: patch the virtual private network (VPN) and that threat has nothing to exploit.$t$::text))
  where id = 'f1cc6e38-a91f-42b6-a7d5-0dfcd44f9548' and content_blocks #>> '{2,caption}' = $t$Remove any link and the risk disappears: patch the VPN and that threat has nothing to exploit.$t$;

-- Professional Ethics
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn the (ISC)2 Code of Ethics: its four canons and the order you resolve conflicts between them, the ethics complaint process that can revoke a certification, and the Internet Activities Board's classic guidance (Request for Comments, RFC 1087) on what counts as unacceptable use of a network, a favorite source for ethics-themed exam scenarios.$t$::text))
  where id = 'ef1131a7-9cee-4a84-b6b0-309502a86251' and content_blocks #>> '{0,overview}' = $t$You'll learn the (ISC)2 Code of Ethics: its four canons and the order you resolve conflicts between them, the ethics complaint process that can revoke a certification, and the Internet Activities Board's classic guidance (RFC 1087) on what counts as unacceptable use of a network, a favorite source for ethics-themed exam scenarios.$t$;

-- Legal, Regulatory, and Compliance Issues
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn the major categories of law that shape security programs (criminal, civil, and administrative), the four types of intellectual property protection, the key characteristics of major privacy regulations like General Data Protection Regulation (GDPR) and Health Insurance Portability and Accountability Act (HIPAA), and the difference between due care and due diligence.$t$::text))
  where id = 'c288b889-3bc0-495b-8c88-eca196754299' and content_blocks #>> '{0,overview}' = $t$You'll learn the major categories of law that shape security programs (criminal, civil, and administrative), the four types of intellectual property protection, the key characteristics of major privacy regulations like GDPR and HIPAA, and the difference between due care and due diligence.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{4,terms,2,short}', to_jsonb($t$GLBA: Gramm-Leach-Bliley Act. Financial institutions and customer financial data.$t$::text))
  where id = 'c288b889-3bc0-495b-8c88-eca196754299' and content_blocks #>> '{4,terms,2,short}' = $t$Financial institutions and customer financial data.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{4,terms,3,short}', to_jsonb($t$SOX: Sarbanes-Oxley Act. Financial reporting controls at public companies.$t$::text))
  where id = 'c288b889-3bc0-495b-8c88-eca196754299' and content_blocks #>> '{4,terms,3,short}' = $t$Financial reporting controls at public companies.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{4,terms,4,short}', to_jsonb($t$FERPA: Family Educational Rights and Privacy Act. Student education records.$t$::text))
  where id = 'c288b889-3bc0-495b-8c88-eca196754299' and content_blocks #>> '{4,terms,4,short}' = $t$Student education records.$t$;

-- Business Continuity & Disaster Recovery Planning
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn the difference between a Business Continuity Plan and a Disaster Recovery Plan, the Business Impact Analysis that has to happen before either can be built, the four key recovery metrics (MTD: maximum tolerable downtime, RTO: recovery time objective, RPO: recovery point objective, WRT: work recovery time) and how they relate to each other, and the three tiers of alternate recovery sites.$t$::text))
  where id = 'e916584e-3a66-4a17-b529-ecb67bea3e77' and content_blocks #>> '{0,overview}' = $t$You'll learn the difference between a Business Continuity Plan and a Disaster Recovery Plan, the Business Impact Analysis that has to happen before either can be built, the four key recovery metrics (MTD, RTO, RPO, WRT) and how they relate to each other, and the three tiers of alternate recovery sites.$t$;

-- Personnel Security Policies and Procedures
update lessons set content_blocks = jsonb_set(content_blocks, '{2,diagram,steps,1,note}', to_jsonb($t$Non-disclosure agreement (NDA) and acceptable-use agreement signed before any access$t$::text))
  where id = '3912bee6-1524-4566-9f62-12a7eecbfb41' and content_blocks #>> '{2,diagram,steps,1,note}' = $t$NDA and acceptable-use agreement signed before any access$t$;

-- Threat Modeling
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn what threat modeling is and why it's done as early as possible in a system's design, Microsoft's STRIDE categories (spoofing, tampering, repudiation, information disclosure, denial of service and elevation of privilege) and how each maps onto a CIA-triad-style property, the DREAD scoring model (damage, reproducibility, exploitability, affected users and discoverability) for prioritizing threats, and the risk-centric, business-aligned approach of PASTA, the Process for Attack Simulation and Threat Analysis.$t$::text))
  where id = 'd39a4921-0bdb-4264-9560-31d2008e01fc' and content_blocks #>> '{0,overview}' = $t$You'll learn what threat modeling is and why it's done as early as possible in a system's design, Microsoft's STRIDE categories and how each maps onto a CIA-triad-style property, the DREAD scoring model for prioritizing threats, and PASTA's risk-centric, business-aligned approach.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{7,text}', to_jsonb($t$Threat modeling isn't a one-time gate. Mature programs revisit it throughout the software development life cycle (SDLC) as the design and attack surface change.$t$::text))
  where id = 'd39a4921-0bdb-4264-9560-31d2008e01fc' and content_blocks #>> '{7,text}' = $t$Threat modeling isn't a one-time gate. Mature programs revisit it throughout the SDLC as the design and attack surface change.$t$;

-- Supply Chain Risk Management
update lessons set content_blocks = jsonb_set(content_blocks, '{5,diagram,steps,1,note}', to_jsonb($t$Service-level agreements (SLAs) with security requirements, right-to-audit clauses$t$::text))
  where id = 'b1b93fcd-ced3-4da2-bec1-0dfeb533fa56' and content_blocks #>> '{5,diagram,steps,1,note}' = $t$SLAs with security requirements, right-to-audit clauses$t$;

-- Data States and Security Controls
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$Expect questions matching a described control (TLS: Transport Layer Security, disk encryption, a secure enclave) to the correct data state, and definitional questions on DLP, CASB, and DRM, these three acronyms are frequently confused with each other and are worth being able to cleanly distinguish.$t$::text))
  where id = 'c5f65a31-59df-4755-9bfd-7dec16388401' and content_blocks #>> '{0,examContext}' = $t$Expect questions matching a described control (TLS, disk encryption, a secure enclave) to the correct data state, and definitional questions on DLP, CASB, and DRM, these three acronyms are frequently confused with each other and are worth being able to cleanly distinguish.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{5,choices,1,text}', to_jsonb($t$AES-256 (Advanced Encryption Standard, 256-bit) disk encryption$t$::text))
  where id = 'c5f65a31-59df-4755-9bfd-7dec16388401' and content_blocks #>> '{5,choices,1,text}' = $t$AES-256 disk encryption$t$;

-- Data Lifecycle Management
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn the stages data moves through from creation to destruction, what data remanence is and why it's a risk, and the National Institute of Standards and Technology (NIST) 800-88 sanitization methods, clear, purge, and destroy, that determine how media should be handled at end of life.$t$::text))
  where id = 'c103e471-cc9b-4b3a-9f6d-3faf59d8549d' and content_blocks #>> '{0,overview}' = $t$You'll learn the stages data moves through from creation to destruction, what data remanence is and why it's a risk, and the NIST 800-88 sanitization methods, clear, purge, and destroy, that determine how media should be handled at end of life.$t$;

-- Asset Retention and End-of-Life Management
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn what drives a data retention policy, why both over-retention and under-retention are genuine risks, the difference between End-of-Life (EOL) and End-of-Support (EOS/EOSL: end of service life) for hardware and software, and why legal holds can override a normal retention schedule.$t$::text))
  where id = 'cedb8584-c10c-4bd4-9176-022a29e9149c' and content_blocks #>> '{0,overview}' = $t$You'll learn what drives a data retention policy, why both over-retention and under-retention are genuine risks, the difference between End-of-Life (EOL) and End-of-Support (EOS/EOSL) for hardware and software, and why legal holds can override a normal retention schedule.$t$;

-- Domain 2 Recap: Asset Security
update lessons set content_blocks = jsonb_set(content_blocks, '{5,choices,2,text}', to_jsonb($t$The CISO (chief information security officer)$t$::text))
  where id = '1727630c-595f-43e5-ab98-4eab59465f09' and content_blocks #>> '{5,choices,2,text}' = $t$The CISO$t$;

-- Secure Design Principles & the Engineering Lifecycle
update lessons set content_blocks = jsonb_set(content_blocks, '{5,caption}', to_jsonb($t$NIST SP 800-160 and ISO/IEC/IEEE 15288, a joint standard from the International Organization for Standardization (ISO), the International Electrotechnical Commission (IEC) and the Institute of Electrical and Electronics Engineers (IEEE), formalize this. Requirements captured early are far cheaper than controls retrofitted after deployment.$t$::text))
  where id = '052c3dca-2de2-42a8-9d64-2fd105523398' and content_blocks #>> '{5,caption}' = $t$NIST SP 800-160 and ISO/IEC/IEEE 15288 formalize this. Requirements captured early are far cheaper than controls retrofitted after deployment.$t$;

-- Evaluation Criteria, Certification, and Accreditation
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn the formal frameworks used to evaluate whether a system meets its claimed security requirements, the legacy TCSEC (Trusted Computer System Evaluation Criteria, Orange Book) and the modern international standard, Common Criteria (ISO/IEC 15408), and the distinction between certification (technical evaluation) and accreditation (management's formal acceptance of risk to operate).$t$::text))
  where id = '6bc58f7f-aed3-4056-b4b6-e5b0a1923824' and content_blocks #>> '{0,overview}' = $t$You'll learn the formal frameworks used to evaluate whether a system meets its claimed security requirements, the legacy TCSEC (Orange Book) and the modern international standard, Common Criteria (ISO/IEC 15408), and the distinction between certification (technical evaluation) and accreditation (management's formal acceptance of risk to operate).$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$Expect to be asked to name TCSEC divisions/orders from lowest to highest assurance, define Common Criteria terms (Protection Profile, Target of Evaluation, Security Target, EAL: Evaluation Assurance Level), and, very commonly, distinguish certification from accreditation, since the two are easy to swap under exam pressure.$t$::text))
  where id = '6bc58f7f-aed3-4056-b4b6-e5b0a1923824' and content_blocks #>> '{0,examContext}' = $t$Expect to be asked to name TCSEC divisions/orders from lowest to highest assurance, define Common Criteria terms (Protection Profile, Target of Evaluation, Security Target, EAL), and, very commonly, distinguish certification from accreditation, since the two are easy to swap under exam pressure.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{3,intro}', to_jsonb($t$The modern international standard that replaced TCSEC and Europe's Information Technology Security Evaluation Criteria (ITSEC). A certification earned in one member country is recognized in others.$t$::text))
  where id = '6bc58f7f-aed3-4056-b4b6-e5b0a1923824' and content_blocks #>> '{3,intro}' = $t$The modern international standard that replaced TCSEC and Europe's ITSEC. A certification earned in one member country is recognized in others.$t$;

-- Security Capabilities of Information Systems
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn the classic, heavily-tested concepts that describe how a trustworthy system enforces its own security, the Trusted Computing Base, the Reference Monitor concept, and the Security Kernel that implements it, plus the concrete hardware and firmware capabilities modern systems build on: memory protection such as address space layout randomization (ASLR) and Data Execution Prevention (DEP, also called NX for no-execute), hardware roots of trust such as the Trusted Platform Module (TPM) and hardware security modules (HSMs), and trusted execution environments/secure enclaves.$t$::text))
  where id = '7be3253f-5b0d-4387-b718-73d27753311b' and content_blocks #>> '{0,overview}' = $t$You'll learn the classic, heavily-tested concepts that describe how a trustworthy system enforces its own security, the Trusted Computing Base, the Reference Monitor concept, and the Security Kernel that implements it, plus the concrete hardware and firmware capabilities modern systems build on: memory protection (ASLR, DEP/NX), hardware roots of trust (TPM, HSM), and trusted execution environments/secure enclaves.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{4,rows,2,values,1}', to_jsonb($t$A certificate authority's root keys (Federal Information Processing Standards, FIPS 140-2/140-3)$t$::text))
  where id = '7be3253f-5b0d-4387-b718-73d27753311b' and content_blocks #>> '{4,rows,2,values,1}' = $t$A certificate authority's root keys (FIPS 140-2/140-3)$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{4,rows,2,values,2}', to_jsonb($t$ARM TrustZone, Intel Software Guard Extensions (SGX)$t$::text))
  where id = '7be3253f-5b0d-4387-b718-73d27753311b' and content_blocks #>> '{4,rows,2,values,2}' = $t$ARM TrustZone, Intel SGX$t$;

-- System Architecture Vulnerabilities: Client-Server, Distributed, Cloud, and Virtualization
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn how the attack surface changes as systems move from a single client-server pair to distributed, multi-tenant cloud and virtualized environments, database aggregation and inference attacks, the risks of peer-to-peer and grid computing, cloud multi-tenancy, and virtualization-specific threats like virtual machine (VM) escape and hypervisor type.$t$::text))
  where id = 'ef076720-367b-4b10-9bd2-96849db7904c' and content_blocks #>> '{0,overview}' = $t$You'll learn how the attack surface changes as systems move from a single client-server pair to distributed, multi-tenant cloud and virtualized environments, database aggregation and inference attacks, the risks of peer-to-peer and grid computing, cloud multi-tenancy, and virtualization-specific threats like VM escape and hypervisor type.$t$;

-- Vulnerabilities in Embedded, IoT, Mobile, and Cyber-Physical Systems
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn the distinct risk profile of embedded and cyber-physical systems like supervisory control and data acquisition/industrial control systems (SCADA/ICS), the common causes of IoT device compromise, and the vulnerabilities specific to mobile devices, plus the mitigations (network segmentation, MDM: mobile device management, secure defaults) used to manage all three.$t$::text))
  where id = 'c1e298b8-1ddb-4587-9ac3-f664acf440e7' and content_blocks #>> '{0,overview}' = $t$You'll learn the distinct risk profile of embedded and cyber-physical systems like SCADA/ICS, the common causes of IoT device compromise, and the vulnerabilities specific to mobile devices, plus the mitigations (network segmentation, MDM, secure defaults) used to manage all three.$t$;

-- Cryptography Fundamentals: Symmetric, Asymmetric, and Hashing
update lessons set content_blocks = jsonb_set(content_blocks, '{1,rows,4,values,1}', to_jsonb($t$Rivest-Shamir-Adleman (RSA), elliptic curve cryptography (ECC), Diffie-Hellman$t$::text))
  where id = '391cce56-e835-45ac-a852-4b926eeca1d2' and content_blocks #>> '{1,rows,4,values,1}' = $t$RSA, ECC, Diffie-Hellman$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{1,rows,4,values,2}', to_jsonb($t$SHA-256 (Secure Hash Algorithm 256), SHA-3 (MD5: Message Digest 5, SHA-1 broken)$t$::text))
  where id = '391cce56-e835-45ac-a852-4b926eeca1d2' and content_blocks #>> '{1,rows,4,values,2}' = $t$SHA-256, SHA-3 (MD5, SHA-1 broken)$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,terms,1,short}', to_jsonb($t$ECB: electronic codebook. Insecure: identical plaintext blocks give identical ciphertext, leaking patterns.$t$::text))
  where id = '391cce56-e835-45ac-a852-4b926eeca1d2' and content_blocks #>> '{2,terms,1,short}' = $t$Insecure: identical plaintext blocks give identical ciphertext, leaking patterns.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,terms,2,short}', to_jsonb($t$CBC: cipher block chaining. Uses an initialization vector to hide those patterns.$t$::text))
  where id = '391cce56-e835-45ac-a852-4b926eeca1d2' and content_blocks #>> '{2,terms,2,short}' = $t$Uses an initialization vector to hide those patterns.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,terms,3,short}', to_jsonb($t$GCM: Galois/Counter Mode. Authenticated encryption: confidentiality plus integrity.$t$::text))
  where id = '391cce56-e835-45ac-a852-4b926eeca1d2' and content_blocks #>> '{2,terms,3,short}' = $t$Authenticated encryption: confidentiality plus integrity.$t$;

-- Public Key Infrastructure (PKI) and Key Management
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn how Public Key Infrastructure lets strangers trust each other's public keys at scale, Certificate Authorities, Registration Authorities, digital certificates, and how revocation is checked via certificate revocation lists (CRLs) and Online Certificate Status Protocol (OCSP), plus the key management lifecycle and the confidentiality/availability tradeoff behind key escrow.$t$::text))
  where id = '14db0970-1727-4ae8-82a7-976020c611ed' and content_blocks #>> '{0,overview}' = $t$You'll learn how Public Key Infrastructure lets strangers trust each other's public keys at scale, Certificate Authorities, Registration Authorities, digital certificates, and how revocation is checked via CRLs and OCSP, plus the key management lifecycle and the confidentiality/availability tradeoff behind key escrow.$t$;

-- Cryptanalytic Attacks and Cryptographic Vulnerabilities
update lessons set content_blocks = jsonb_set(content_blocks, '{4,terms,2,short}', to_jsonb($t$Watches central processing unit (CPU) cache access patterns.$t$::text))
  where id = 'b7820372-1adc-45bf-aef7-03b9702078ca' and content_blocks #>> '{4,terms,2,short}' = $t$Watches CPU cache access patterns.$t$;

-- Facility Security Controls
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You'll learn the physical access control mechanisms that regulate entry (locks, access control vestibules, badges, biometrics, guards), the environmental controls that protect equipment (HVAC: heating, ventilation and air conditioning, humidity, power), and fire safety fundamentals, fire classes, detection methods, and suppression systems.$t$::text))
  where id = '6b4c407f-1567-4d60-b83c-614f5a72b847' and content_blocks #>> '{0,overview}' = $t$You'll learn the physical access control mechanisms that regulate entry (locks, access control vestibules, badges, biometrics, guards), the environmental controls that protect equipment (HVAC, humidity, power), and fire safety fundamentals, fire classes, detection methods, and suppression systems.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{3,terms,2,short}', to_jsonb($t$Uninterruptible power supply (UPS) for short gaps, generators for long outages.$t$::text))
  where id = '6b4c407f-1567-4d60-b83c-614f5a72b847' and content_blocks #>> '{3,terms,2,short}' = $t$UPS for short gaps, generators for long outages.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{6,choices,2,text}', to_jsonb($t$A CCTV (closed-circuit television) camera$t$::text))
  where id = '6b4c407f-1567-4d60-b83c-614f5a72b847' and content_blocks #>> '{6,choices,2,text}' = $t$A CCTV camera$t$;

-- The OSI and TCP/IP Models
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn the Open Systems Interconnection (OSI) model's seven layers and the Transmission Control Protocol/Internet Protocol (TCP/IP) model's four layers, how they map to each other, and how to place any given protocol, device, or attack at the correct layer. This vocabulary is the foundation the rest of Domain 4 is built on.$t$::text))
  where id = 'f74e0117-c11a-4677-b1b8-e34f70ce61f7' and content_blocks #>> '{0,overview}' = $t$You will learn the OSI model's seven layers and the TCP/IP model's four layers, how they map to each other, and how to place any given protocol, device, or attack at the correct layer. This vocabulary is the foundation the rest of Domain 4 is built on.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$"At which layer does X operate" is one of the most frequently recurring question shapes in this domain, for a device (switch, router, firewall), a protocol (Address Resolution Protocol or ARP, IP, TCP, Hypertext Transfer Protocol or HTTP), or an attack (media access control or MAC flooding, IP spoofing, session hijacking). Memorizing the 7 OSI layers in order, cold, pays off across dozens of later questions in this domain and in Domain 3.$t$::text))
  where id = 'f74e0117-c11a-4677-b1b8-e34f70ce61f7' and content_blocks #>> '{0,examContext}' = $t$"At which layer does X operate" is one of the most frequently recurring question shapes in this domain, for a device (switch, router, firewall), a protocol (ARP, IP, TCP, HTTP), or an attack (MAC flooding, IP spoofing, session hijacking). Memorizing the 7 OSI layers in order, cold, pays off across dozens of later questions in this domain and in Domain 3.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,rows,0,values,2}', to_jsonb($t$HTTP, Domain Name System (DNS), Simple Mail Transfer Protocol (SMTP), File Transfer Protocol (FTP)$t$::text))
  where id = 'f74e0117-c11a-4677-b1b8-e34f70ce61f7' and content_blocks #>> '{2,rows,0,values,2}' = $t$HTTP, DNS, SMTP, FTP$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,rows,3,values,1}', to_jsonb($t$Segment (TCP) / datagram (UDP: User Datagram Protocol)$t$::text))
  where id = 'f74e0117-c11a-4677-b1b8-e34f70ce61f7' and content_blocks #>> '{2,rows,3,values,1}' = $t$Segment (TCP) / datagram (UDP)$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,rows,3,values,3}', to_jsonb($t$Synchronize (SYN) flood, port scanning$t$::text))
  where id = 'f74e0117-c11a-4677-b1b8-e34f70ce61f7' and content_blocks #>> '{2,rows,3,values,3}' = $t$SYN flood, port scanning$t$;

-- IP Addressing and Subnetting
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn how IPv4 and IPv6 addressing work, which address ranges are reserved for private use, how Classless Inter-Domain Routing (CIDR) notation expresses a subnet, and how network address translation (NAT) translates between private and public addresses. The exam tests concepts and recognition here far more than subnet-math calculation.$t$::text))
  where id = '82898f4e-6767-4371-9dd1-b957e71fc7fd' and content_blocks #>> '{0,overview}' = $t$You will learn how IPv4 and IPv6 addressing work, which address ranges are reserved for private use, how CIDR notation expresses a subnet, and how NAT translates between private and public addresses. The exam tests concepts and recognition here far more than subnet-math calculation.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{4,heading}', to_jsonb($t$NAT vs. PAT (port address translation)$t$::text))
  where id = '82898f4e-6767-4371-9dd1-b957e71fc7fd' and content_blocks #>> '{4,heading}' = $t$NAT vs. PAT$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{6,choices,0,text}', to_jsonb($t$DHCP (Dynamic Host Configuration Protocol)$t$::text))
  where id = '82898f4e-6767-4371-9dd1-b957e71fc7fd' and content_blocks #>> '{6,choices,0,text}' = $t$DHCP$t$;

