-- Secure Network Protocols
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn the secure replacements for common legacy cleartext protocols, how IPsec provides authentication and encryption at the network layer (including AH (Authentication Header) vs ESP (Encapsulating Security Payload) and transport vs tunnel mode), and the basic sequence of a TLS handshake.$t$::text))
  where id = 'fcf57ce4-9dc0-46bf-8d35-9a5890e01ae0' and content_blocks #>> '{0,overview}' = $t$You will learn the secure replacements for common legacy cleartext protocols, how IPsec provides authentication and encryption at the network layer (including AH vs ESP and transport vs tunnel mode), and the basic sequence of a TLS handshake.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$Protocol-to-secure-replacement mapping (Telnet to SSH (Secure Shell), FTP to SFTP (SSH File Transfer Protocol), HTTP to HTTPS (HTTP Secure)) is asked directly and often. IPsec's AH-vs-ESP and transport-vs-tunnel distinctions are also classic, specific exam facts, know which mode encrypts payload only vs. the entire original packet.$t$::text))
  where id = 'fcf57ce4-9dc0-46bf-8d35-9a5890e01ae0' and content_blocks #>> '{0,examContext}' = $t$Protocol-to-secure-replacement mapping (Telnet to SSH, FTP to SFTP, HTTP to HTTPS) is asked directly and often. IPsec's AH-vs-ESP and transport-vs-tunnel distinctions are also classic, specific exam facts, know which mode encrypts payload only vs. the entire original packet.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,rows,1,values,1}', to_jsonb($t$SFTP (over SSH) or FTPS (FTP Secure, with TLS)$t$::text))
  where id = 'fcf57ce4-9dc0-46bf-8d35-9a5890e01ae0' and content_blocks #>> '{2,rows,1,values,1}' = $t$SFTP (over SSH) or FTPS (with TLS)$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,rows,3,label}', to_jsonb($t$SNMP (Simple Network Management Protocol) v1 / v2c$t$::text))
  where id = 'fcf57ce4-9dc0-46bf-8d35-9a5890e01ae0' and content_blocks #>> '{2,rows,3,label}' = $t$SNMP v1 / v2c$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,rows,4,values,1}', to_jsonb($t$DNSSEC (DNS Security Extensions, signed responses)$t$::text))
  where id = 'fcf57ce4-9dc0-46bf-8d35-9a5890e01ae0' and content_blocks #>> '{2,rows,4,values,1}' = $t$DNSSEC (signed responses)$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{5,caption}', to_jsonb($t$TLS, the successor to deprecated Secure Sockets Layer (SSL), is hybrid encryption in action.$t$::text))
  where id = 'fcf57ce4-9dc0-46bf-8d35-9a5890e01ae0' and content_blocks #>> '{5,caption}' = $t$TLS, the successor to deprecated SSL, is hybrid encryption in action.$t$;

-- Network Devices and Segmentation
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn the evolution of firewall technology across generations (packet-filtering, stateful, next-generation, proxy/WAF: web application firewall), how virtual local area networks (VLANs) logically separate a physical network, what a demilitarized zone (DMZ) is for, and how micro-segmentation extends these ideas toward a zero trust design.$t$::text))
  where id = 'f3ef6f14-5427-407e-8ca4-0fc220417050' and content_blocks #>> '{0,overview}' = $t$You will learn the evolution of firewall technology across generations (packet-filtering, stateful, next-generation, proxy/WAF), how VLANs logically separate a physical network, what a DMZ is for, and how micro-segmentation extends these ideas toward a zero trust design.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{1,diagram,rungs,0,note}', to_jsonb($t$Terminates and inspects the whole application conversation; a WAF targets web attacks like Structured Query Language (SQL) injection and cross-site scripting (XSS).$t$::text))
  where id = 'f3ef6f14-5427-407e-8ca4-0fc220417050' and content_blocks #>> '{1,diagram,rungs,0,note}' = $t$Terminates and inspects the whole application conversation; a WAF targets web attacks like SQL injection and XSS.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{7,text}', to_jsonb($t$Stateless filters judge each packet alone; stateful firewalls remember connections; next-generation firewalls (NGFWs) see applications. DMZs hold what the internet must reach.$t$::text))
  where id = 'f3ef6f14-5427-407e-8ca4-0fc220417050' and content_blocks #>> '{7,text}' = $t$Stateless filters judge each packet alone; stateful firewalls remember connections; NGFWs see applications. DMZs hold what the internet must reach.$t$;

-- Wireless Network Security
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn how Wi-Fi security has evolved from broken Wired Equivalent Privacy (WEP) through Wi-Fi Protected Access (WPA), WPA2, and WPA3, the difference between personal (PSK: pre-shared key) and enterprise (802.1X) authentication modes, and the common wireless-specific attacks: rogue access points, evil twins, and deauthentication attacks.$t$::text))
  where id = 'ed588a29-80e1-4dd4-89c6-3b58b5fac109' and content_blocks #>> '{0,overview}' = $t$You will learn how Wi-Fi security has evolved from broken WEP through WPA, WPA2, and WPA3, the difference between personal (PSK) and enterprise (802.1X) authentication modes, and the common wireless-specific attacks: rogue access points, evil twins, and deauthentication attacks.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$WPA2-vs-WPA3 differences are a frequent, specific exam topic, particularly that WPA3 replaces the 4-way handshake with Simultaneous Authentication of Equals (SAE), closing the offline dictionary attack that plagued WPA2-PSK. Recognizing rogue AP vs. evil twin vs. deauthentication attack scenarios is equally common.$t$::text))
  where id = 'ed588a29-80e1-4dd4-89c6-3b58b5fac109' and content_blocks #>> '{0,examContext}' = $t$WPA2-vs-WPA3 differences are a frequent, specific exam topic, particularly that WPA3 replaces the 4-way handshake with SAE, closing the offline dictionary attack that plagued WPA2-PSK. Recognizing rogue AP vs. evil twin vs. deauthentication attack scenarios is equally common.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{1,diagram,steps,1,note}', to_jsonb($t$Interim fix using Temporal Key Integrity Protocol (TKIP). Now weak and obsolete.$t$::text))
  where id = 'ed588a29-80e1-4dd4-89c6-3b58b5fac109' and content_blocks #>> '{1,diagram,steps,1,note}' = $t$Interim fix using TKIP. Now weak and obsolete.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,rows,0,values,1}', to_jsonb($t$Each user's own credentials via Remote Authentication Dial-In User Service (RADIUS)$t$::text))
  where id = 'ed588a29-80e1-4dd4-89c6-3b58b5fac109' and content_blocks #>> '{2,rows,0,values,1}' = $t$Each user's own credentials via RADIUS$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{3,cue,1}', to_jsonb($t$"same SSID (service set identifier)", "impersonates"$t$::text))
  where id = 'ed588a29-80e1-4dd4-89c6-3b58b5fac109' and content_blocks #>> '{3,cue,1}' = $t$"same SSID", "impersonates"$t$;

-- Network Access Control and Endpoint Security
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn how Network Access Control (NAC) verifies and enforces policy on devices before granting network access, how 802.1X/Extensible Authentication Protocol (EAP) provides port-based authentication for both wired and wireless connections, and how Zero Trust Network Access (ZTNA) extends these ideas into continuous, per-session verification.$t$::text))
  where id = '2f7d30a9-feb7-4bad-84d4-c40388456cb7' and content_blocks #>> '{0,overview}' = $t$You will learn how Network Access Control (NAC) verifies and enforces policy on devices before granting network access, how 802.1X/EAP provides port-based authentication for both wired and wireless connections, and how Zero Trust Network Access (ZTNA) extends these ideas into continuous, per-session verification.$t$;

-- Remote Access and VPN Technologies
update lessons set content_blocks = jsonb_set(content_blocks, '{3,rows,2,values,1}', to_jsonb($t$Full visibility: filtering, DLP, intrusion detection system (IDS) see everything$t$::text))
  where id = '70c50729-a54e-40df-81d4-02dfa33e8f81' and content_blocks #>> '{3,rows,2,values,1}' = $t$Full visibility: filtering, DLP, IDS see everything$t$;

-- Voice, Multimedia Collaboration, and Converged Protocols
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn the security implications of running voice traffic over IP networks (VoIP: Voice over Internet Protocol), the role of Session Initiation Protocol (SIP) in setting up those calls, common VoIP-specific attacks like eavesdropping and toll fraud, and the risks introduced when voice, video, and data converge onto one network.$t$::text))
  where id = 'e0378370-8715-4cc5-8975-aae56eb10bcc' and content_blocks #>> '{0,overview}' = $t$You will learn the security implications of running voice traffic over IP networks (VoIP), the role of SIP in setting up those calls, common VoIP-specific attacks like eavesdropping and toll fraud, and the risks introduced when voice, video, and data converge onto one network.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,terms,2,short}', to_jsonb($t$Real-time Transport Protocol: carries the actual voice media.$t$::text))
  where id = 'e0378370-8715-4cc5-8975-aae56eb10bcc' and content_blocks #>> '{2,terms,2,short}' = $t$Carries the actual voice media.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,terms,3,short}', to_jsonb($t$SRTP: Secure Real-time Transport Protocol. Encrypt the media and the signaling.$t$::text))
  where id = 'e0378370-8715-4cc5-8975-aae56eb10bcc' and content_blocks #>> '{2,terms,3,short}' = $t$Encrypt the media and the signaling.$t$;

-- Software-Defined Networks, Virtualization, and Cloud Connectivity
update lessons set content_blocks = jsonb_set(content_blocks, '{2,terms,1,short}', to_jsonb($t$SDN ideas for wide area links: steers traffic across Multiprotocol Label Switching (MPLS), broadband and LTE (Long-Term Evolution, a 4G cellular standard) by policy and conditions.$t$::text))
  where id = '86a0a006-e36f-4615-a084-90e86d776b1b' and content_blocks #>> '{2,terms,1,short}' = $t$SDN ideas for wide area links: steers traffic across MPLS, broadband and LTE by policy and conditions.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,terms,4,short}', to_jsonb($t$Content delivery network: edge servers caching content near users; also absorbs some DDoS traffic.$t$::text))
  where id = '86a0a006-e36f-4615-a084-90e86d776b1b' and content_blocks #>> '{2,terms,4,short}' = $t$Edge servers caching content near users; also absorbs some DDoS traffic.$t$;

-- Access Control Fundamentals: Subjects, Objects, and the AAA Model
update lessons set content_blocks = jsonb_set(content_blocks, '{3,heading}', to_jsonb($t$The access control process (IAAA, identification, authentication, authorization and accountability)$t$::text))
  where id = 'cd469b12-1fdf-4eb2-b5b5-d1e357f1ef2a' and content_blocks #>> '{3,heading}' = $t$The access control process (IAAA)$t$;

-- Authentication Factors, Multi-Factor Authentication, and Biometrics
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$The 'two passwords isn't MFA' trap is one of the most reliably tested facts in this domain, MFA requires factors from different categories. Biometric metric definitions (FAR: false acceptance rate, FRR: false rejection rate, CER: crossover error rate) are also asked directly and precisely, so know which error type each one measures.$t$::text))
  where id = 'ba51a66a-11af-41ca-82c7-1500142d5cfa' and content_blocks #>> '{0,examContext}' = $t$The 'two passwords isn't MFA' trap is one of the most reliably tested facts in this domain, MFA requires factors from different categories. Biometric metric definitions (FAR, FRR, CER) are also asked directly and precisely, so know which error type each one measures.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{3,terms,2,short}', to_jsonb($t$EER: equal error rate. Where FAR equals FRR. **Lower is better**; the standard number for comparing systems.$t$::text))
  where id = 'ba51a66a-11af-41ca-82c7-1500142d5cfa' and content_blocks #>> '{3,terms,2,short}' = $t$Where FAR equals FRR. **Lower is better**; the standard number for comparing systems.$t$;

-- Access Control Models: DAC, MAC, RBAC, and ABAC
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn the four major access control models, discretionary (DAC), mandatory (MAC), role-based (RBAC) and attribute-based (ABAC) access control, what governs each one's access decisions, and how to recognize which model a described scenario is using.$t$::text))
  where id = 'b5a28839-a35b-49d8-bd9c-0a54359dad54' and content_blocks #>> '{0,overview}' = $t$You will learn the four major access control models, Discretionary, Mandatory, Role-Based, and Attribute-Based, what governs each one's access decisions, and how to recognize which model a described scenario is using.$t$;

-- Identity Management and Directory Services
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn how directory services like Lightweight Directory Access Protocol (LDAP) centrally store identity information, how Kerberos provides ticket-based network authentication, and how RADIUS and Terminal Access Controller Access-Control System (TACACS+) differ as the two dominant AAA protocols for network device and remote access authentication.$t$::text))
  where id = 'b27b9de1-0c7a-45cd-8aaa-6d7b18420aeb' and content_blocks #>> '{0,overview}' = $t$You will learn how directory services like LDAP centrally store identity information, how Kerberos provides ticket-based network authentication, and how RADIUS and TACACS+ differ as the two dominant AAA protocols for network device and remote access authentication.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$Kerberos's ticket flow (AS (Authentication Service) to TGT (ticket-granting ticket) to TGS (Ticket-Granting Service) to service ticket) and its Key Distribution Center (KDC) single point of failure are precise, frequently tested facts. RADIUS-vs-TACACS+ (transport protocol, encryption scope, and whether AAA functions are combined or separated) is an equally standard comparison question.$t$::text))
  where id = 'b27b9de1-0c7a-45cd-8aaa-6d7b18420aeb' and content_blocks #>> '{0,examContext}' = $t$Kerberos's ticket flow (AS to TGT to TGS to service ticket) and its KDC single point of failure are precise, frequently tested facts. RADIUS-vs-TACACS+ (transport protocol, encryption scope, and whether AAA functions are combined or separated) is an equally standard comparison question.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{5,choices,3,text}', to_jsonb($t$SAML (Security Assertion Markup Language)$t$::text))
  where id = 'b27b9de1-0c7a-45cd-8aaa-6d7b18420aeb' and content_blocks #>> '{5,choices,3,text}' = $t$SAML$t$;

-- Federated Identity Management and Single Sign-On
