  where id = '2fddfdab-98dd-4f4a-9db2-5d47a11a3706' and content_blocks #>> '{3,rows,2,values,2}' = $t$ID token (a JWT)$t$;

-- Identity as a Service (IDaaS) and Third-Party/Cloud Identity Integration
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn what Identity as a Service (IDaaS) is, the tradeoffs of outsourcing identity infrastructure to a cloud provider, and the two standards, System for Cross-domain Identity Management (SCIM) for automated provisioning and just-in-time (JIT) provisioning at first login, that connect an IDaaS or federated identity source to the applications that rely on it.$t$::text))
  where id = 'b3844d16-643c-4c25-9a89-88131ea018e1' and content_blocks #>> '{0,overview}' = $t$You will learn what Identity as a Service (IDaaS) is, the tradeoffs of outsourcing identity infrastructure to a cloud provider, and the two standards, SCIM for automated provisioning and JIT provisioning at first login, that connect an IDaaS or federated identity source to the applications that rely on it.$t$;

-- Session Management and Access Control Attacks
