  where id = '38f3946f-95af-48f8-8f4b-9c8d2d1914e4' and content_blocks #>> '{5,rows,1,values,1}' = $t$Customer A views customer B's orders by changing an ID in the URL$t$;

-- Privileged Access Management (PAM)
update lessons set content_blocks = jsonb_set(content_blocks, '{4,example}', to_jsonb($t$A database administrator (DBA) checks out the production root password for a 30-minute change window. When the window closes, the vault rotates the password.$t$::text))
