  where id = '0ad0a3fa-f051-4721-90d6-c501ea68d71d' and content_blocks #>> '{6,prompt}' = $t$A security engineer runs a scan to confirm that a newly applied firewall rule blocks inbound SMB traffic. What is this?$t$;

-- Security Control Testing Techniques
update lessons set content_blocks = jsonb_set(content_blocks, '{1,terms,0,short}', to_jsonb($t$Examining logs for events, violations and anomalies, usually through a security information and event management (SIEM). Only as good as what's logged.$t$::text))
  where id = '53879970-2e5b-4d96-800d-1eeb6f378c22' and content_blocks #>> '{1,terms,0,short}' = $t$Examining logs for events, violations and anomalies, usually through a SIEM. Only as good as what's logged.$t$;
