  where id = '53879970-2e5b-4d96-800d-1eeb6f378c22' and content_blocks #>> '{1,terms,5,short}' = $t$Verifying configuration matches a required baseline, such as CIS Benchmarks.$t$;

-- Code Review and Software Testing
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn the three main automated approaches to testing software for security flaws, static analysis (SAST), dynamic analysis (DAST: dynamic application security testing), and interactive analysis (IAST: interactive application security testing), plus fuzzing and manual code review, and what each approach can and cannot catch.$t$::text))
  where id = 'e04d0bc9-8449-4ef0-b647-c66f6c569cb8' and content_blocks #>> '{0,overview}' = $t$You will learn the three main automated approaches to testing software for security flaws, static analysis (SAST), dynamic analysis (DAST), and interactive analysis (IAST), plus fuzzing and manual code review, and what each approach can and cannot catch.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{1,rows,1,values,2}', to_jsonb($t$During functional or quality assurance (QA) testing$t$::text))
  where id = 'e04d0bc9-8449-4ef0-b647-c66f6c569cb8' and content_blocks #>> '{1,rows,1,values,2}' = $t$During functional or QA testing$t$;

