-- Analyzing Test Output and Reporting
update lessons set content_blocks = jsonb_set(content_blocks, '{5,terms,0,short}', to_jsonb($t$Every finding has an owner and a date, tracked in a ticketing or governance, risk and compliance (GRC) system.$t$::text))
  where id = '2faff0e5-1eb9-43c3-b1ee-40f990db3522' and content_blocks #>> '{5,terms,0,short}' = $t$Every finding has an owner and a date, tracked in a ticketing or GRC system.$t$;

-- Investigations and Evidence Handling
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$Order of volatility is a frequently tested, precise sequence, most volatile evidence (CPU registers/cache, then RAM (random access memory)) is collected before less volatile evidence (disk, then backups/archives), because volatile evidence is lost first if the system keeps running or is powered off. Chain of custody is equally standard: any gap in the documented handling of evidence can make it inadmissible, regardless of how technically sound the collection was.$t$::text))
  where id = '67761876-b985-4e1d-ba62-d105ca61d706' and content_blocks #>> '{0,examContext}' = $t$Order of volatility is a frequently tested, precise sequence, most volatile evidence (CPU registers/cache, then RAM) is collected before less volatile evidence (disk, then backups/archives), because volatile evidence is lost first if the system keeps running or is powered off. Chain of custody is equally standard: any gap in the documented handling of evidence can make it inadmissible, regardless of how technically sound the collection was.$t$;

-- Logging and Monitoring
update lessons set content_blocks = jsonb_set(content_blocks, '{1,terms,4,short}', to_jsonb($t$User and entity behavior analytics: baselines each user's and system's normal behavior and flags deviations.$t$::text))
  where id = 'a9246639-6635-4521-bbd4-21da149383c2' and content_blocks #>> '{1,terms,4,short}' = $t$Baselines each user's and system's normal behavior and flags deviations.$t$;

-- Resource Protection and Asset Management
update lessons set content_blocks = jsonb_set(content_blocks, '{1,terms,1,short}', to_jsonb($t$Following location and custody with barcodes or radio-frequency identification (RFID) so nothing quietly disappears.$t$::text))
  where id = '6cd79f67-028f-40e9-b269-e27411f4ab7e' and content_blocks #>> '{1,terms,1,short}' = $t$Following location and custody with barcodes or RFID so nothing quietly disappears.$t$;

-- Detective and Preventive Security Controls
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn the core technical controls used to detect and prevent attacks: firewalls, the distinction between an IDS and an intrusion prevention system (IPS), signature-based vs. anomaly-based detection, allowlisting vs. blocklisting, honeypots/honeynets, anti-malware, and sandboxing, and how these controls fit together as layers rather than substitutes for one another.$t$::text))
  where id = '7edde4f5-36af-4fd9-a1ed-6e439e21cd3e' and content_blocks #>> '{0,overview}' = $t$You will learn the core technical controls used to detect and prevent attacks: firewalls, the distinction between an IDS and an IPS, signature-based vs. anomaly-based detection, allowlisting vs. blocklisting, honeypots/honeynets, anti-malware, and sandboxing, and how these controls fit together as layers rather than substitutes for one another.$t$;

-- Patch and Vulnerability Management
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn how organizations systematically find and fix known weaknesses before attackers exploit them: vulnerability scanning (credentialed vs. uncredentialed), how vulnerabilities are cataloged and scored via Common Vulnerabilities and Exposures (CVE) and CVSS, the patch management lifecycle from identification through verification, how patches get prioritized, and virtual patching as a stopgap when a real patch isn't yet available.$t$::text))
  where id = '4794cf63-1a70-4a80-8100-e753936e9534' and content_blocks #>> '{0,overview}' = $t$You will learn how organizations systematically find and fix known weaknesses before attackers exploit them: vulnerability scanning (credentialed vs. uncredentialed), how vulnerabilities are cataloged and scored via CVE and CVSS, the patch management lifecycle from identification through verification, how patches get prioritized, and virtual patching as a stopgap when a real patch isn't yet available.$t$;

-- Recovery Strategies and System Resilience
update lessons set content_blocks = jsonb_set(content_blocks, '{2,example}', to_jsonb($t$Production data on the storage area network (SAN), a nightly copy to a backup appliance, and a weekly copy to immutable cloud storage.$t$::text))
  where id = '6104fb19-e077-456f-9c11-119b1aae29da' and content_blocks #>> '{2,example}' = $t$Production data on the SAN, a nightly copy to a backup appliance, and a weekly copy to immutable cloud storage.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{4,terms,2,short}', to_jsonb($t$Redundant array of independent disks: disk arrays that survive individual drive failures.$t$::text))
  where id = '6104fb19-e077-456f-9c11-119b1aae29da' and content_blocks #>> '{4,terms,2,short}' = $t$Disk arrays that survive individual drive failures.$t$;

-- Development Methodologies: Waterfall, Agile, DevOps, and DevSecOps
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$Waterfall vs. Agile is a classic comparison: Waterfall is sequential and hard to change once a phase is done, while Agile is iterative and built around adapting to change. Know Scrum's core artifacts/ceremonies (backlog, sprint, daily standup, retrospective) and Kanban's visual, work in progress (WIP) limited workflow. CI/CD (continuous integration/continuous deployment) and DevSecOps, security automated directly into the pipeline rather than bolted on afterward, are especially high-yield, current-relevance topics.$t$::text))
  where id = '0f722383-1d7b-458f-9132-dd9455f1080b' and content_blocks #>> '{0,examContext}' = $t$Waterfall vs. Agile is a classic comparison: Waterfall is sequential and hard to change once a phase is done, while Agile is iterative and built around adapting to change. Know Scrum's core artifacts/ceremonies (backlog, sprint, daily standup, retrospective) and Kanban's visual, WIP-limited workflow. CI/CD (continuous integration/continuous deployment) and DevSecOps, security automated directly into the pipeline rather than bolted on afterward, are especially high-yield, current-relevance topics.$t$;

-- Software Capability Maturity Models: CMMI, SAMM, and BSIMM
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn the frameworks organizations use to measure and improve how mature their software development, and specifically their secure development, practices are: the general-purpose Capability Maturity Model Integration (CMMI), and the security-focused Software Assurance Maturity Model (SAMM) and Building Security In Maturity Model (BSIMM) models.$t$::text))
  where id = '18827c83-bb43-4de9-a588-8905bcf08498' and content_blocks #>> '{0,overview}' = $t$You will learn the frameworks organizations use to measure and improve how mature their software development, and specifically their secure development, practices are: the general-purpose CMMI, and the security-focused SAMM and BSIMM models.$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{2,columns,0}', to_jsonb($t$OWASP (Open Worldwide Application Security Project) SAMM$t$::text))
  where id = '18827c83-bb43-4de9-a588-8905bcf08498' and content_blocks #>> '{2,columns,0}' = $t$OWASP SAMM$t$;

-- Security of Development Environments and Code Repositories
update lessons set content_blocks = jsonb_set(content_blocks, '{0,overview}', to_jsonb($t$You will learn how development environments and source code itself need to be protected: keeping development, test, and production environments properly separated, securing the source code repository and its history, and locking down the developer toolchain (IDEs: integrated development environments, build tools, and secrets) that produces the software in the first place.$t$::text))
  where id = '00a979e1-226a-405e-9007-32cfc444801b' and content_blocks #>> '{0,overview}' = $t$You will learn how development environments and source code itself need to be protected: keeping development, test, and production environments properly separated, securing the source code repository and its history, and locking down the developer toolchain (IDEs, build tools, and secrets) that produces the software in the first place.$t$;

-- Assessing Acquired Software: COTS, Open Source, and Cloud Services
update lessons set content_blocks = jsonb_set(content_blocks, '{0,examContext}', to_jsonb($t$The shared responsibility model is a heavily tested concept: know that as you move from IaaS to PaaS to SaaS, the provider takes on progressively more of the security responsibility, while the customer retains progressively less, but the customer is never fully off the hook (data, access management, and configuration remain customer responsibilities even in SaaS). Also expect questions distinguishing the specific risks of COTS (vendor trust, patching cadence, EULA/licensing (end-user license agreement) terms) versus open source (community support and maintenance quality vary widely, but source code is inspectable).$t$::text))
  where id = '927919a8-02df-44c3-850d-2c8463ceff54' and content_blocks #>> '{0,examContext}' = $t$The shared responsibility model is a heavily tested concept: know that as you move from IaaS to PaaS to SaaS, the provider takes on progressively more of the security responsibility, while the customer retains progressively less, but the customer is never fully off the hook (data, access management, and configuration remain customer responsibilities even in SaaS). Also expect questions distinguishing the specific risks of COTS (vendor trust, patching cadence, EULA/licensing terms) versus open source (community support and maintenance quality vary widely, but source code is inspectable).$t$;
update lessons set content_blocks = jsonb_set(content_blocks, '{4,prompt}', to_jsonb($t$A company moves its customer relationship management (CRM) to a SaaS provider. Which responsibility stays with the company?$t$::text))
  where id = '927919a8-02df-44c3-850d-2c8463ceff54' and content_blocks #>> '{4,prompt}' = $t$A company moves its CRM to a SaaS provider. Which responsibility stays with the company?$t$;

