-- What the CySA+ Exam Actually Tests
update lessons set content_blocks = jsonb_set(content_blocks, '{1,text}', to_jsonb($t$CySA+ is CompTIA's intermediate certification for security operations center (SOC) analysts, incident responders and threat hunters. It sits between Security+ and advanced credentials like CISSP, and it's heavy on hands-on detection, analysis and response.$t$::text))
  where id = '2b8b3720-a83c-40f6-b406-952cf72a71f5' and content_blocks #>> '{1,text}' = $t$CySA+ is CompTIA's intermediate certification for SOC analysts, incident responders and threat hunters. It sits between Security+ and advanced credentials like CISSP, and it's heavy on hands-on detection, analysis and response.$t$;

